static int p2d89_emit_arrows_basic(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 pts[]={-16384,-4096,4096,-4096,4096,-10240,16384,0,4096,10240,4096,4096,-16384,4096};static const p2d89_q14 dbl[]={-16384,0,-8192,-8192,-8192,-4096,8192,-4096,8192,-8192,16384,0,8192,8192,8192,4096,-8192,4096,-8192,8192};p2d89_u16 t;if(id==P2D89_SHAPE_DOUBLE_ARROW_HORIZONTAL)return p2d89_i_poly(dbl,10U,1,p);if(id==P2D89_SHAPE_DOUBLE_ARROW_VERTICAL)return p2d89_i_rot_poly(dbl,10U,16384U,1,p);if(id==P2D89_SHAPE_ARROW_RIGHT)t=0U;else if(id==P2D89_SHAPE_ARROW_DOWN)t=16384U;else if(id==P2D89_SHAPE_ARROW_LEFT)t=32768U;else if(id==P2D89_SHAPE_ARROW_UP)t=49152U;else if(id==P2D89_SHAPE_ARROW_DOWN_RIGHT)t=8192U;else if(id==P2D89_SHAPE_ARROW_DOWN_LEFT)t=24576U;else if(id==P2D89_SHAPE_ARROW_UP_LEFT)t=40960U;else if(id==P2D89_SHAPE_ARROW_UP_RIGHT)t=57344U;else return 0;return p2d89_i_rot_poly(pts,7U,t,1,p);}
const P2D89_Submodule p2d89_submodule_arrows_basic = { { P2D89_MODULE_ARROWS, "arrows", "basic", (unsigned int)(sizeof(shapes)/sizeof(shapes[0])) }, shapes, p2d89_emit_arrows_basic };
